code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def runs(edge, color):
        found = []
        start = None
        for i, v in enumerate(edge + [None]):
            if v == color and start is None:
                start = i
            elif v != color and start is not None:
                found.append(list(range(start, i)))
                start = None
        return found

    candidates = []
    for orient in ('vertical', 'horizontal'):
        if orient == 'vertical':
            a, b = list(grid[0]), list(grid[-1])
        else:
            a = [grid[r][0] for r in range(h)]
            b = [grid[r][-1] for r in range(h)]
        common = (set(a) & set(b)) - {bg}
        for wall in common:
            ar, br = runs(a, wall), runs(b, wall)
            if ar and br:
                candidates.append((sum(map(len, ar)) + sum(map(len, br)), orient, wall, ar, br))
    if not candidates:
        return out
    _, orient, wall, aruns, bruns = max(candidates, key=lambda x: x[0])

    ink_colors = [c for c in Counter(v for row in grid for v in row) if c not in (bg, wall)]
    if not ink_colors:
        return out
    ink = min(ink_colors, key=lambda c: Counter(v for row in grid for v in row)[c])

    # Pair the opposing edge bars by their order and position within each bar.
    pairs = []
    for aa in aruns:
        for bb in bruns:
            n = min(len(aa), len(bb))
            pairs.extend((aa[i], bb[i]) for i in range(n))

    for x, y in pairs:
        if orient == 'vertical':
            rays = [(0, x, 1), (h - 1, y, -1)]
        else:
            rays = [(x, 0, 1), (y, w - 1, -1)]
        active = []
        for r, c, step in rays:
            cells = []
            rr, cc = r + (step if orient == 'vertical' else 0), c + (step if orient == 'horizontal' else 0)
            dr, dc = (step, 0) if orient == 'vertical' else (0, step)
            while 0 <= rr < h and 0 <= cc < w:
                cells.append((rr, cc))
                rr += dr; cc += dc
            markers = [(rr, cc) for rr, cc in cells if grid[rr][cc] == ink]
            active.append((cells, markers))
        if not any(markers for _, markers in active):
            continue
        for cells, markers in active:
            if markers:
                # The ray stops at its first marker when traveling inward from this edge.
                marker = markers[0]
                for rr, cc in cells:
                    if (rr, cc) == marker:
                        out[rr][cc] = 4
                        break
                    out[rr][cc] = ink
            else:
                for rr, cc in cells:
                    out[rr][cc] = ink
    return out
'''
